TLM.f("Tempora/Quad1-5",{"officium":"Feria Sexta Quattuor Temporum","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad1-0","sections":{"Introitus":[{"k":"ref","la":"Ps 24:17; 24:18"},{"k":"text","la":"De necessitátibus meis éripe me, Dómine: vide humilitátem meam et labórem meum, et dimítte ómnia peccáta mea."},{"k":"ref","la":"Ps 24:1-2"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"De necessitátibus meis éripe me, Dómine: vide humilitátem meam et labórem meum, et dimítte ómnia peccáta mea."}],"Oratio":[{"k":"text","la":"Esto, Dómine, propítius plebi tuæ: et, quam tibi facis esse devótam, benígno réfove miserátus auxílio."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Ezechiélis Prophétæ"},{"k":"ref","la":"Ezech 18:20-28"},{"k":"text","la":"Hæc dicit Dóminus Deus: Anima, quæ peccáverit, ipsa moriétur: fílius non portábit iniquitátem patris, et pater non portábit iniquitátem fílii: justítia justi super eum erit, et impíetas ímpii erit super eum. Si autem ímpius égerit pæniténtiam ab ómnibus peccátis suis, quæ operátus est, et custodíerit ómnia præcépta mea, et fécerit judícium et justítiam: vita vivet, et non moriétur. Omnium iniquitátum ejus, quas operátus est, non recordábor: in justítia sua, quam operátus est, vivet. Numquid voluntátis meæ est mors ímpii, dicit Dóminus Deus, et non ut convertátur a viis suis, et vivat? Si autem avérterit se justus a justítia sua, et fécerit iniquitátem secúndum omnes abominatiónes, quas operári solet ímpius, numquid vivet? omnes justítiæ ejus, quas fécerat, non recordabúntur: in prævaricatióne, qua prævaricátus est, et in peccáto suo, quod peccávit, in ipsis moriétur. Et dixístis: Non est æqua via Dómini. Audíte ergo, domus Israël: Numquid via mea non est æqua, et non magis viæ vestræ pravæ sunt? Cum enim avérterit se justus a justítia sua, et fécerit iniquitátem, moriétur in eis: in injustítia, quam operátus est, moriétur. Et cum avérterit se ímpius ab impietáte sua, quam operátus est, et fécerit judícium et justítiam: ipse ánimam suam vivificábit. Consíderans enim, et avértens se ab ómnibus iniquitátibus suis, quas operátus est, vita vivet, et non moriétur, ait Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 85:2; 85:6"},{"k":"text","la":"Salvum fac servum tuum. Deus meus, sperántem in te."},{"k":"text","la":"Auribus pércipe, Dómine, oratiónem meam.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 5:1-15"},{"k":"text","la":"In illo témpore: Erat dies festus Judæórum, et ascéndit Jesus Jerosólymam. Est autem Jerosólymis Probática piscína, quæ cognominátur hebráice Bethsáida, quinque pórticus habens. In his jacébat multitúdo magna languéntium, cæcórum, claudórum, aridórum exspectántium aquæ motum. Angelus autem Dómini descendébat secúndum tempus in piscínam, et movebátur aqua. Et, qui prior descendísset in piscínam post motiónem aquæ, sanus fiébat, a quacúmque detinebátur infirmitáte. Erat autem quidam homo ibi, trigínta et octo annos habens in infirmitáte sua. Hunc cum vidísset Jesus jacéntem, et cognovísset, quia jam multum tempus habéret, dicit ei: Vis sanus fíeri? Respóndit ei lánguidus: Dómine, hóminem non hábeo, ut, cum turbáta fúerit aqua, mittat me in piscínam: dum vénio enim ego, álius ante me descéndit. Dicit ei Jesus: Surge, tolle grabátum tuum, et ámbula. Et statim sanus factus est homo ille: et sústulit grabátum suum, et ambulábat. Erat autem sábbatum in die illo. Dicébant ergo Judǽi illi, qui sanátus fúerat: Sábbatum est, non licet tibi tóllere grabátum tuum. Respóndit eis: Qui me sanum fecit, ille mihi dixit: Tolle grabátum tuum, et ámbula. Interrogavérunt ergo eum: Quis est ille homo, qui dixit tibi: Tolle grabátum tuum et ámbula? Is autem, qui sanus fúerat efféctus, nesciébat, quis esset. Jesus enim declinávit a turba constitúta in loco. Póstea invénit eum Jesus in templo, et dixit illi: Ecce, sanus factus es: jam noli peccáre, ne detérius tibi áliquid contíngat. Abiit ille homo, et nuntiávit Judǽis, quia Jesus esset, qui fecit eum sanum."}],"Offertorium":[{"k":"ref","la":"Ps 102:2; 102:5"},{"k":"text","la":"Bénedic, ánima mea, Dómino, et noli oblivísci omnes retributiónes ejus: et renovábitur, sicut áquilæ, juvéntus tua."}],"Secreta":[{"k":"text","la":"Súscipe, quǽsumus, Dómine, múnera nostris obláta servítiis: et tua propítius dona sanctífica."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 6:11"},{"k":"text","la":"Erubéscant et conturbéntur omnes inimíci mei: avertántur retrórsum, et erubéscant valde velóciter."}],"Postcommunio":[{"k":"text","la":"Per hujus, Dómine, operatiónem mystérii, et vítia nostra purgéntur, et justa desidéria compleántur."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Exáudi nos, miséricors Deus: et méntibus nostris grátiæ tuæ lumen osténde."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a0bba6fe357a9e5a":{"t":"Ps 24, 17 i 18, Ps 24, 1-2\n(Ps 24, 17 i 18) Iz tjeskoba mojih izbavi me, Gospodine. Pogledaj poniženje moje i muku moju i oprosti sve grijehe moje. (Ps 24, 1-2) Tebi, Gospodine, uzdižem dušu svoju, Bože moj, u tebe se uzdam, ne daj da se zastidim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 24, 17 i 18) Iz tjeskoba mojih izbavi me, Gospodine. Pogledaj poniženje moje i muku moju i oprosti sve grijehe moje."},"6b8484b2b51c7a8f":{"t":"<i>Pomolimo se</i>.\nBudi, Gospodine, milostiv svome narodu, i njega koji ti je odan okrijepi milosno blagonaklonom pomoću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"6a58b13141612a2a":{"t":"Ez 18, 20-28\nČitanje Ezekiela proroka. Ovo govori Gospodin Bog: Onaj koji sagriješi umrijet će. Sin neće snositi očevih nedjela, niti će otac odgovarati za sinovljeva bezakonja. Pravedniku će se suditi po njegovoj pravednosti, a bezbožniku po njegovoj bezbožnosti. Ako se bezbožnik pokaje za svoje grijehe što ih je počinio i bude držao sve moje zapovijedi i djelovao po pravdi, živjet će i neće umrijeti. Njegovih bezakonja neću se sjećati, živjet će po svojoj pravednosti. Zar da ja želim smrt bezbožnika, pita Gospodin Bog, a ne da se obrati od svojih stranputica? Ili zar bi živio pravednik, ako bi otpao od svoje pravde i živio zlo kako živi bezbožnik? Njegova pravedna djela što ih je činio neće se spominjati. Umrijet će u zlu što ga je učinio i u prestupku kojim je sagriješio. I još govorite: Gospodnji put nije prav! Čujte, dome Izraelov: Zar moj put nije prav? Ta nije li jasno da su vaši putovi krivi? Kada se pravednik odvrati od svoje pravednosti i učini zlo, umrijet će u tome, umrijet će u nepravdi što ju je počinio. A kada se bezbožnik obrati od svoje bezbožnosti koju je činio i bude živio po pravu i pravednosti, on će oživjeti. Kad promisli i obrati se od sviju svojih bezakonja što ih je počinio neće umrijeti, nego će živjeti, govori Gospodin svemogući."},"3ef2e1eeecbc1660":{"t":"Ps 85, 2 i 6\nBože moj, spasi slugu svoga, koji se u te uzda. Poslušaj, Gospodine, molitvu moju.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega."},"1f4b5dbf5222de1a":{"t":"Iv 5, 1-15\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bio je židovski blagdan i Isus se uputi u Jeruzalem. U Jeruzalemu je kod Ovčjih vrata ribnjak s pet trijemova koji se hebrejski zove Betsaida. U njima je ležalo vrlo mnogo bolesnika slijepih, hromih, sušičavih koji su očekivali da se uzgiba voda. Anđeo je naime Gospodnji silazio od vremena do vremena u ribnjak i uzgibao vodu. I onaj koji bi prvi sišao u vodu kad se uzgibala, ozdravio bi, pa bolovao on od bilo koje bolesti. Ondje je ležao čovjek koji je bolovao trideset i osam godina. Kada ga Isus opazi i dozna da je već dugo vremena bolestan, upita ga: Bi li htio ozdraviti? Bolesnik odgovori: Gospodine, nemam nikoga koji bi me spustio u ribnjak kada se uzgiba voda, a dok ja siđem, već se drugi spusti prije mene. Isus mu reče: Ustani, uzmi svoju postelju i hodi! I smjesta ozdravi taj čovjek, uzme svoju postelju i prohoda. A bila je subota pa su Židovi govorili ozdravljeniku: Subota je, ne smiješ nositi svoju postelju. On im odgovori: Onaj koji me ozdravio reče mi: Uzmi svoju postelju i hodi. Upitaju ga: Tko je taj čovjek koji ti reče: Uzmi svoju postelju i hodi? Ali ozdravljenik nije znao tko je, jer se Isus odmah udaljio od prisutnog mnoštva. Poslije ga Isus sretne u hramu i reče mu: Eto, ozdravio si. Nemoj više griješiti da te ne snađe što gore. Onaj čovjek pođe i javi Židovima da ga je ozdravio Isus."},"32c5a47ef1f5c32e":{"t":"Ps 102, 2 i 5\nBlagoslivljaj, dušo moja, Gospodina i ne zaboravljaj ni jednog dobročinstva njegova, i obnovit će se kao u orla mladost tvoja."},"c5d7822016eeebcc":{"t":"Primi, molimo, Gospodine, darove našom službom prikazane i milostivo posveti svoje darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"58256ea1e8371b46":{"t":"Ps 6, 11\nNeka se zastide i smetu svi neprijatelji moji, neka uzmaknu i neka se zastide veoma brzo."},"1acbcdbc746602b4":{"t":"<i>Pomolimo se</i>.\nDjelovanjem ovoga otajstva, Gospodine, neka se očiste naše opačine i ispune pravedne želje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"25b71b71ac4dd9e7":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nUsliši nas, milosrdni Bože, i pokaži našim dušama svjetlo svoje milosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
